/bin/bash -lc "cat > src/util/checkoutRequest.mjs <<'EOF'
export function buildCheckoutRequest({
  cartCode,
  shippingOptionId,
  currency,
  paymentToken,
  paymentModule,
  amount,
  agreedToTerms,
  comments,
}) {
  return {
    method: 'POST',
    path: "'`cart/${cartCode}/checkout`,
    body: {
      quoteId: shippingOptionId,
      currency,
      termsAccepted: agreedToTerms,
      orderNote: comments,
      payment: {
        paymentType: '"'CREDITCARD',
        transactionType: 'CAPTURE',
        processor: paymentModule,
        cardToken: paymentToken,
        amount,
      },
    },
  };
}
EOF
node --input-type=module -e \"import('./src/util/checkoutRequest.mjs').then(m => console.log(JSON.stringify(m.buildCheckoutRequest({cartCode:'ABC123',shippingOptionId:7,currency:'GBP',paymentToken:'tok_123',paymentModule:'stripe',amount:'10.00',agreedToTerms:true,comments:'gift wrap'}), null, 2)))\""
